/**
 * Maps an original media path (/uploads/...) to its optimized WebP copy generated by
 * scripts/optimize-images.mjs. `small` selects the 800px-wide variant.
 */
export const opt = (src: string, small = false) => {
  if (!src.startsWith('/uploads/') || !/\.(jpe?g|png|webp)$/i.test(src)) return src;
  return src.replace(/^\/uploads\//, '/opt/').replace(/\.(jpe?g|png|webp)$/i, small ? '-800.webp' : '.webp');
};
